import csv
import io
import re


_NUMBER = re.compile(r"^[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?$")


def parse_csv(raw_csv: str):
    expected_width = 2
    records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False))

    def is_number(value):
        return bool(_NUMBER.fullmatch(value.strip()))

    header_index = None
    for index, row in enumerate(records):
        if len(row) != expected_width or not row:
            continue
        if all(not is_number(value) for value in row):
            for following in records[index + 1:]:
                if not following:
                    continue
                if len(following) == expected_width and all(is_number(value) for value in following):
                    header_index = index
                break
        if header_index is not None:
            break

    if header_index is None:
        header_index = next(
            (index for index, row in enumerate(records) if len(row) == expected_width),
            None,
        )

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = list(records[header_index])
    if columns and columns[0].startswith("\ufeff"):
        columns[0] = columns[0].lstrip("\ufeff")

    rows = []
    for row in records[header_index + 1:]:
        row = list(row)
        if len(row) < expected_width:
            row.extend([""] * (expected_width - len(row)))
        elif len(row) > expected_width:
            row = row[:expected_width - 1] + [",".join(row[expected_width - 1:])]
        rows.append(row)

    return {"columns": columns, "rows": rows}
